@o3 w.request.context sort=room name="Focus pod"
@r1 w.request.request act=change mood=do predicate=set
@r1.t w.request.target request=$r1 family=room mode=existing determiner=definite fill=written name="Cedar room" thing=$o1 thing=$o2 thing=$o3
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=room.id value="Cedar room" operator=eq phase=selector thing=$o1 thing=$o2 thing=$o3
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=room.name value=Review operator=eq phase=result
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=room.seats value="8" operator=eq phase=result

@o1 w.request.context sort=person name=Ana
@o2 w.request.context sort=person name=Lee
@o3 w.request.context sort=meeting name="Weekly review"
@r1 w.request.request act=change mood=do predicate=change
@r1.t w.request.target request=$r1 family=meeting mode=existing determiner=definite fill=written name="Weekly review" thing=$o3
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=meeting.id value="Weekly review" operator=eq phase=selector thing=$o3
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=meeting.day value=Monday operator=eq phase=result
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=meeting.time value="10:00" operator=eq phase=result
@r1.c4 w.request.constraint request=$r1 on=attribute attribute=meeting.people value="Ana and Lee" operator=eq phase=result thing=$o1 thing=$o2

@o1 w.request.context sort=meeting name="Weekly review"
@r1 w.request.request act=remove mood=do predicate=delete
@r1.t w.request.target request=$r1 family=meeting mode=existing determiner=definite fill=written name="Weekly review" thing=$o1
